import{_ as t,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Rapid Processing of NASA Satellite Data Stored with Ceph - Kevin Hrpcek & Steve Dutcher","description":"","frontmatter":{"title":"Rapid Processing of NASA Satellite Data Stored with Ceph - Kevin Hrpcek & Steve Dutcher","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["NASA satellite data","Ceph storage","Distributed storage","High throughput computing","Data processing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Rapid_Processing_of_NASA_Satellite_Data_Stored_with_Ceph_-_Kevin_Hrpcek_Steve_Dutcher.md","filePath":"posts/2019/Rapid_Processing_of_NASA_Satellite_Data_Stored_with_Ceph_-_Kevin_Hrpcek_Steve_Dutcher.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Rapid_Processing_of_NASA_Satellite_Data_Stored_with_Ceph_-_Kevin_Hrpcek_Steve_Dutcher.md"};function p(a,e,s,_,n,S){return i(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 使用Ceph进行NASA卫星数据的快速处理和存储</p><p><strong>与会人员</strong>： Kevin（主持人）、Steve（发言人），来自威斯康星大学麦迪逊分校SSE C团队</p><p><strong>会议内容</strong>：</p><p><strong>1. SSE C团队介绍</strong></p><ul><li>SSE C团队成立于50多年前，是卫星遥感技术的先驱中心，负责地球遥感成像、传感器数据验证与校准、数值天气预报建模等工作。</li><li>主要项目包括：NASA Vera卫星大气步骤项目，旨在生成2级和3级NASA产品，并与NASA科学团队合作，高效处理大量数据。</li></ul><p><strong>2. 数据处理挑战</strong></p><ul><li>使用Vera卫星等极地轨道卫星收集数据，每天产生大量数据，需要高效处理。</li><li>使用MODIS传感器等卫星数据，进行数据验证与校准，需要长期存储。</li><li>使用TROPICS项目，需要收集来自6颗立方星的数据，数据量更大。</li></ul><p><strong>3. 存储解决方案</strong></p><ul><li>预计每年需要增长1PB存储空间，需要良好的数据复制和海量存储。</li><li>使用Ceph作为存储解决方案，已使用4-5年，效果良好。</li><li>每天数据摄入量达600GB，产品生成量达500GB，其他产品生成量达700GB。</li></ul><p><strong>4. 数据处理流程</strong></p><ul><li>使用RabbitMQ进行消息传递，将感兴趣的数据文件发送到计算节点。</li><li>使用Ceph存储文件，并记录文件信息到数据库。</li><li>开发了PG Track工具，用于跟踪文件存储状态。</li><li>开发了Ceph Sleight工具，用于简化Ceph操作。</li></ul><p><strong>5. 容器化与自动化</strong></p><ul><li>使用Kubernetes进行容器化部署，例如PDS Serve服务。</li><li>使用HTCondor进行计算任务调度，支持科学团队进行数据处理。</li></ul><p><strong>6. 工具与架构</strong></p><ul><li>开发了FUSE层，为用户提供POSIX访问权限。</li><li>开发了Track Everything工具，用于跟踪Ceph集群中的对象。</li></ul><p><strong>7. 挑战与经验</strong></p><ul><li>集群规模不断增长，需要关注设置和优化。</li><li>遇到过集群故障，但未丢失任何对象。</li><li>Ceph性能良好，可满足高吞吐量计算需求。</li></ul><p><strong>8. 未来计划</strong></p><ul><li>移动BlueStore，解决大文件存储限制问题。</li><li>可能升级Ceph到最新版本，以利用新技术。</li></ul><p><strong>行动计划</strong>：</p><ul><li>持续关注Ceph社区，跟进新技术。</li><li>优化集群设置，提高性能。</li><li>开发更多工具，简化数据处理流程。</li></ul><p><strong>总结</strong>： SSE C团队通过使用Ceph等开源技术，成功解决了NASA卫星数据快速处理和存储的挑战，为科学研究和气候变化研究提供了有力支持。</p>',23)])])}const u=t(o,[["render",p]]);export{h as __pageData,u as default};
